var fbRowA = [175, 310, 445];
var fbRowB = [713, 883, 1053];

/* ---------- groups ---------- */
var gA = fbDraw.group();
var gAEdges = gA.group(), gANodes = gA.group(), gAIns = gA.group();
var gB = fbDraw.group();
var gBArr = gB.group(), gBNodes = gB.group(), gBIns = gB.group();
var gMark = fbDraw.group();
var fbHL = fbDraw.group();

/* ---------- helpers ---------- */
function fbTxt(g, s, cx, cy, size, color, italic, weight) {
  var t = g.text(String(s)).font({
    family: FB_SERIF, size: size, anchor: 'middle',
    style: italic ? 'italic' : 'normal', weight: weight || 'normal'
  }).fill(color);
  t.center(cx, cy);
  return t;
}
function fbHalo(t) {
  t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 4.5, 'stroke-linejoin': 'round' });
  return t;
}
function fbArrow(g, x1, y1, x2, y2, color, w, dash) {
  var l = g.line(x1, y1, x2, y2).stroke({ color: color, width: w || 2 });
  if (dash) l.attr('stroke-dasharray', dash);
  l.marker('end', fbMarker(color));
  return l;
}
function fbPath(g, d, color, w, dash) {
  var p = g.path(d).fill('none').stroke({ color: color, width: w || 2 });
  if (dash) p.attr('stroke-dasharray', dash);
  p.marker('end', fbMarker(color));
  return p;
}

var fbPtr = [];
function fbReg(el, owner, kind, lx, ly, w) {
  fbPtr.push({ el: el, owner: owner, kind: kind, lx: lx, ly: ly, base: '#000', w: w || 2 });
  return el;
}

/* ---------- circular doubly linked list rails (panel b) ---------- */
function fbDrawList(g, ids, y) {
  var xs = ids.map(function (id) { return fbN[id].x; });
  var n = ids.length;
  var yF = y - 11, yB = y + 11, rt = y - 62, rb = y + 62, rad = 14;
  var xL = xs[0] - FB_R - 44, xR = xs[n - 1] + FB_R + 44;
  var i;
  for (i = 0; i < n - 1; i++) {
    fbReg(fbArrow(g, xs[i] + FB_R + 2, yF, xs[i + 1] - FB_R - 2, yF, '#000', 2),
      ids[i], 'right', (xs[i] + xs[i + 1]) / 2, yF - 13);
    fbReg(fbArrow(g, xs[i + 1] - FB_R - 2, yB, xs[i] + FB_R + 2, yB, '#000', 2),
      ids[i + 1], 'left', (xs[i] + xs[i + 1]) / 2, yB + 24);
  }
  var df = 'M' + (xs[n - 1] + FB_R + 2) + ',' + yF + ' H' + (xR - rad) +
    ' Q' + xR + ',' + yF + ' ' + xR + ',' + (yF - rad) +
    ' V' + (rt + rad) + ' Q' + xR + ',' + rt + ' ' + (xR - rad) + ',' + rt +
    ' H' + (xL + rad) + ' Q' + xL + ',' + rt + ' ' + xL + ',' + (rt + rad) +
    ' V' + (yF - rad) + ' Q' + xL + ',' + yF + ' ' + (xL + rad) + ',' + yF +
    ' H' + (xs[0] - FB_R - 2);
  fbReg(fbPath(g, df, '#000', 2), ids[n - 1], 'right', (xL + xR) / 2, rt - 13);
  var db = 'M' + (xs[0] - FB_R - 2) + ',' + yB + ' H' + (xL + rad) +
    ' Q' + xL + ',' + yB + ' ' + xL + ',' + (yB + rad) +
    ' V' + (rb - rad) + ' Q' + xL + ',' + rb + ' ' + (xL + rad) + ',' + rb +
    ' H' + (xR - rad) + ' Q' + xR + ',' + rb + ' ' + xR + ',' + (rb - rad) +
    ' V' + (yB + rad) + ' Q' + xR + ',' + yB + ' ' + (xR - rad) + ',' + yB +
    ' H' + (xs[n - 1] + FB_R + 2);
  fbReg(fbPath(g, db, '#000', 2), ids[0], 'left', (xL + xR) / 2, rb + 20);
}

/* ---------- parent / child pointer pairs (panel b) ---------- */
function fbDrawPC(g, cKey, pKey, designated) {
  var C = fbN[cKey], P = fbN[pKey];
  var cy = fbRowB[C.d], py = fbRowB[P.d];
  var dx = P.x - C.x, dy = py - cy, L = Math.sqrt(dx * dx + dy * dy);
  var ux = dx / L, uy = dy / L, nx = -uy, ny = ux;
  var off = designated ? 8 : 0;
  var a1x = C.x + ux * FB_R + nx * off, a1y = cy + uy * FB_R + ny * off;
  var a2x = P.x - ux * (FB_R + 2) + nx * off, a2y = py - uy * (FB_R + 2) + ny * off;
  fbReg(fbArrow(g, a1x, a1y, a2x, a2y, '#000', 2), cKey, 'p',
    (a1x + a2x) / 2 + nx * 20, (a1y + a2y) / 2 + ny * 20);
  if (designated) {
    var b1x = P.x - ux * FB_R - nx * off, b1y = py - uy * FB_R - ny * off;
    var b2x = C.x + ux * (FB_R + 2) - nx * off, b2y = cy + uy * (FB_R + 2) - ny * off;
    fbReg(fbArrow(g, b1x, b1y, b2x, b2y, '#000', 2), pKey, 'child',
      (b1x + b2x) / 2 - nx * 24, (b1y + b2y) / 2 - ny * 24);
  }
}

/* ---------- nodes ---------- */
function fbNeighbors(k) {
  var L = fbN[k].list, i = fbN[k].idx;
  return { left: L[(i - 1 + L.length) % L.length], right: L[(i + 1) % L.length] };
}
function fbSummary(k) {
  var nb = fbNeighbors(k);
  return k + ':  p=' + (fbN[k].p || 'NIL') + '  child=' + (FBCHILD[k] || 'NIL') +
    '  left=' + nb.left + '  right=' + nb.right;
}
function fbPopupText(k) {
  var nb = fbNeighbors(k);
  var s = 'x.p = ' + (fbN[k].p || 'NIL') + ',  x.child = ' + (FBCHILD[k] || 'NIL') +
    ',  x.left = ' + nb.left + ',  x.right = ' + nb.right + '. ';
  if (nb.left === k) s += 'This node is alone in its sibling list, so left and right point back at itself — a circular list of one. ';
  else s += 'left and right run around a circular doubly linked sibling list, so there is no head or tail to special-case. ';
  s += fbN[k].m ? 'It is marked (black): it has lost one child since becoming a child itself.' :
    'It is unmarked (gray): it has not lost a child since becoming a child.';
  return s;
}
function fbDrawNode(g, k, y) {
  var nd = fbN[k];
  g.circle(2 * FB_R).center(nd.x, y).fill(nd.m ? '#111' : FB_GRAY).stroke({ color: '#000', width: 1.6 });
  fbTxt(g, k, nd.x, y + 1, 30, nd.m ? '#fff' : '#000', false, nd.m ? 'bold' : 'normal');
  var hit = g.circle(2 * FB_R + 10).center(nd.x, y).fill('#000').opacity(0).css('cursor', 'pointer');
  hit.on('mousemove', function (e) { showTooltip(fbSummary(k), e); });
  hit.on('mouseleave', function () { hideTooltip(); });
  hit.on('click', function () {
    fbSelect(k);
    showPopup('Node ' + k + (fbN[k].m ? ' (marked)' : ''), fbPopupText(k));
  });
}

/* ---------- H.min ---------- */
function fbHmin(g, tx, ty, ax, ay1, ay2) {
  fbHalo(fbTxt(g, 'H.min', tx, ty, 32, '#000', true));
  fbArrow(g, ax, ay1, ax, ay2, '#000', 2.4);
}

/* ---------- panel (a) ---------- */
var fbSegA317 = null;
(function buildA() {
  var y0 = fbRowA[0], roots = fbLists[0].ids, i;
  for (i = 0; i < roots.length - 1; i++) {
    var seg = gAEdges.line(fbN[roots[i]].x + FB_R, y0, fbN[roots[i + 1]].x - FB_R, y0)
      .stroke({ color: '#000', width: 2, dasharray: '10,9' });
    if (roots[i] === 3) fbSegA317 = seg;
  }
  fbDefs.forEach(function (nd) {
    if (!nd.p) return;
    var P = fbN[nd.p];
    var cx = nd.x, cy = fbRowA[nd.d], px = P.x, py = fbRowA[P.d];
    var dx = px - cx, dy = py - cy, L = Math.sqrt(dx * dx + dy * dy), ux = dx / L, uy = dy / L;
    gAEdges.line(cx + ux * FB_R, cy + uy * FB_R, px - ux * FB_R, py - uy * FB_R)
      .stroke({ color: '#222', width: 1.8 });
  });
  fbDefs.forEach(function (nd) { fbDrawNode(gANodes, nd.k, fbRowA[nd.d]); });
  fbHalo(fbTxt(gANodes, '(a)', 62, 175, 36, '#000'));
  fbHmin(gANodes, 720, 32, 720, 58, 138);
})();

/* ---------- panel (b) ---------- */
(function buildB() {
  fbLists.forEach(function (L) { fbDrawList(gBArr, L.ids, fbRowB[L.d]); });
  fbDefs.forEach(function (nd) {
    if (!nd.p) return;
    fbDrawPC(gBArr, nd.k, nd.p, FBCHILD[nd.p] === nd.k);
  });
  fbDefs.forEach(function (nd) { fbDrawNode(gBNodes, nd.k, fbRowB[nd.d]); });
  fbHalo(fbTxt(gBNodes, '(b)', 62, 713, 36, '#000'));
  fbHmin(gBNodes, 720, 578, 720, 604, 640);
})();

/* ---------- pointer highlighting ---------- */
var fbSel = null;
function fbClearHL() {
  fbPtr.forEach(function (p) {
    p.el.stroke({ color: p.base, width: p.w });
    p.el.marker('end', fbMarker(p.base));
  });
  fbHL.clear();
  fbSel = null;
}
function fbSelect(k) {
  fbClearHL();
  fbSel = k;
  fbPtr.forEach(function (p) {
    if (p.owner !== k) return;
    p.el.stroke({ color: FB_OR, width: 3 });
    p.el.marker('end', fbMarker(FB_OR));
    p.el.front();
    fbHalo(fbTxt(fbHL, p.kind, p.lx, p.ly, 21, FB_OR, true));
  });
  fbHL.circle(2 * FB_R + 18).center(fbN[k].x, fbRowA[fbN[k].d]).fill('none').stroke({ color: FB_OR, width: 3 });
  fbHL.circle(2 * FB_R + 18).center(fbN[k].x, fbRowB[fbN[k].d]).fill('none').stroke({ color: FB_OR, width: 3 });
}
function trigger_clearSel() { fbClearHL(); }

/* ---------- marked-node emphasis ---------- */
function fbShowMarked(on) {
  gMark.clear();
  if (!on) return;
  [18, 39, 26].forEach(function (k) {
    gMark.circle(2 * FB_R + 20).center(fbN[k].x, fbRowA[fbN[k].d]).fill('none')
      .stroke({ color: FB_OR, width: 3, dasharray: '6,5' });
    gMark.circle(2 * FB_R + 20).center(fbN[k].x, fbRowB[fbN[k].d]).fill('none')
      .stroke({ color: FB_OR, width: 3, dasharray: '6,5' });
  });
}

/* ---------- insertion overlay ---------- */
var FBPH = { 'before': 0, 'new node created': 1, 'spliced into root list': 2, 'H.min updated': 3, 'done': 4 };
var fbPhase = 'before';

function fbNewNode(g, x, y, solid) {
  g.circle(2 * FB_R).center(x, y).fill(solid ? '#cfe9d6' : '#f2fbf5')
    .stroke({ color: FB_GR, width: 2.4, dasharray: solid ? null : '6,4' });
  fbTxt(g, '21', x, y + 1, 30, '#0d5c2e', false, 'bold');
}
function fbSelfLoops(g, x, y, color) {
  var yF = y - 9, yB = y + 9, rt = y - 46, rb = y + 46, rad = 12;
  var xL = x - FB_R - 32, xR = x + FB_R + 32;
  fbPath(g, 'M' + (x + FB_R) + ',' + yF + ' H' + (xR - rad) + ' Q' + xR + ',' + yF + ' ' + xR + ',' + (yF - rad) +
    ' V' + (rt + rad) + ' Q' + xR + ',' + rt + ' ' + (xR - rad) + ',' + rt + ' H' + (xL + rad) +
    ' Q' + xL + ',' + rt + ' ' + xL + ',' + (rt + rad) + ' V' + (yF - rad) + ' Q' + xL + ',' + yF + ' ' + (xL + rad) + ',' + yF +
    ' H' + (x - FB_R), color, 2.2, '6,4');
  fbPath(g, 'M' + (x - FB_R) + ',' + yB + ' H' + (xL + rad) + ' Q' + xL + ',' + yB + ' ' + xL + ',' + (yB + rad) +
    ' V' + (rb - rad) + ' Q' + xL + ',' + rb + ' ' + (xL + rad) + ',' + rb + ' H' + (xR - rad) +
    ' Q' + xR + ',' + rb + ' ' + xR + ',' + (rb - rad) + ' V' + (yB + rad) + ' Q' + xR + ',' + yB + ' ' + (xR - rad) + ',' + yB +
    ' H' + (x + FB_R), color, 2.2, '6,4');
}

function fbRenderInsert() {
  var s = FBPH[fbPhase] || 0, X = 925;
  gAIns.clear(); gBIns.clear();
  var fade = s >= 2;
  fbPtr.forEach(function (p) {
    if ((p.owner === 3 && p.kind === 'right') || (p.owner === 17 && p.kind === 'left'))
      p.el.opacity(fade ? 0.12 : 1);
  });
  if (fbSegA317) fbSegA317.opacity(fade ? 0.12 : 1);
  if (s === 0) return;

  var dash = (s === 4) ? null : '8,6';

  /* panel (a) */
  if (s === 1) {
    fbNewNode(gAIns, X, 62, false);
    fbHalo(fbTxt(gAIns, 'new single-node tree', X + 30, 112, 20, '#0d5c2e', true));
  } else {
    fbArrow(gAIns, fbN[3].x + FB_R, fbRowA[0], X - FB_R, fbRowA[0], FB_GR,2.4, dash);
    fbArrow(gAIns, X + FB_R, fbRowA[0], fbN[17].x - FB_R, fbRowA[0], FB_GR, 2.4, dash);
    fbNewNode(gAIns, X, fbRowA[0], s === 4);
    fbHalo(fbTxt(gAIns, 'O(1): 4 pointer writes', 995, 100, 20, '#0d5c2e', true));
    if (s >= 3) fbHalo(fbTxt(gAIns, '21 > 3  \u21D2  H.min unchanged', 1255, 100, 20, FB_OR, true));
  }

  /* panel (b) */
  var yF = fbRowB[0] - 11, yB = fbRowB[0] + 11;
  if (s === 1) {
    fbNewNode(gBIns, X, 592, false);
    fbSelfLoops(gBIns, X, 592, FB_GR);
    fbHalo(fbTxt(gBIns, 'x.left = x.right = x', 1175, 585, 20, '#0d5c2e', true));
  } else {
    fbArrow(gBIns, fbN[3].x + FB_R + 2, yF, X - FB_R - 2, yF, FB_GR, 2.4, dash);
    fbArrow(gBIns, X + FB_R + 2, yF, fbN[17].x - FB_R - 2, yF, FB_GR, 2.4, dash);
    fbArrow(gBIns, X - FB_R - 2, yB, fbN[3].x + FB_R + 2, yB, FB_GR, 2.4, dash);
    fbArrow(gBIns, fbN[17].x - FB_R - 2, yB, X + FB_R + 2, yB, FB_GR, 2.4, dash);
    fbNewNode(gBIns, X, fbRowB[0], s === 4);
    fbHalo(fbTxt(gBIns, '4 pointer updates \u2192 O(1)', 960, 802, 21, '#0d5c2e', true));
    if (s >= 3) fbHalo(fbTxt(gBIns, '21 > 3  \u21D2  H.min stays at 3', 1085, 608, 21, FB_OR, true));
  }
}

