  fbHmin(gBNodes, 720, 578, 720, 604, 640);
})();

/* ---------- pointer highlighting ---------- */
var fbSel = null;
function fbClearHL() {
  fbPtr.forEach(function (p) {
    p.el.stroke({ color: p.base, width: p.w });
    p.el.marker('end', fbMarker(p.base));
  });
  fbHL.clear();
  fbSel = null;
}
function fbSelect(k) {
  fbClearHL();
  fbSel = k;
  fbPtr.forEach(function (p) {
    if (p.owner !== k) return;
    p.el.stroke({ color: FB_OR, width: 3 });
    p.el.marker('end', fbMarker(FB_OR));
    p.el.front();
    fbHalo(fbTxt(fbHL, p.kind, p.lx, p.ly, 21, FB_OR, true));
  });
  fbHL.circle(2 * FB_R + 18).center(fbN[k].x, fbRowA[fbN[k].d]).fill('none').stroke({ color: FB_OR, width: 3 });
  fbHL.circle(2 * FB_R + 18).center(fbN[k].x, fbRowB[fbN[k].d]).fill('none').stroke({ color: FB_OR, width: 3 });
}
function trigger_clearSel() { fbClearHL(); }

/* ---------- marked-node emphasis ---------- */
function fbShowMarked(on) {
  gMark.clear();
  if (!on) return;
  [18, 39, 26].forEach(function (k) {
    gMark.circle(2 * FB_R + 20).center(fbN[k].x, fbRowA[fbN[k].d]).fill('none')
      .stroke({ color: FB_OR, width: 3, dasharray: '6,5' });
    gMark.circle(2 * FB_R + 20).center(fbN[k].x, fbRowB[fbN[k].d]).fill('none')
      .stroke({ color: FB_OR, width: 3, dasharray: '6,5' });
  });
}

/* ---------- insertion overlay ---------- */
var FBPH = { 'before': 0, 'new node created': 1, 'spliced into root list': 2, 'H.min updated': 3, 'done': 4 };
var fbPhase = 'before';

function fbNewNode(g, x, y, solid) {
  g.circle(2 * FB_R).center(x, y).fill(solid ? '#cfe9d6' : '#f2fbf5')
    .stroke({ color: FB_GR, width: 2.4, dasharray: solid ? null : '6,4' });
  fbTxt(g, '21', x, y + 1, 30, '#0d5c2e', false, 'bold');
}
function fbSelfLoops(g, x, y, color) {
  var yF = y - 9, yB = y + 9, rt = y - 46, rb = y + 46, rad = 12;
  var xL = x - FB_R - 32, xR = x + FB_R + 32;
  fbPath(g, 'M' + (x + FB_R) + ',' + yF + ' H' + (xR - rad) + ' Q' + xR + ',' + yF + ' ' + xR + ',' + (yF - rad) +
    ' V' + (rt + rad) + ' Q' + xR + ',' + rt + ' ' + (xR - rad) + ',' + rt + ' H' + (xL + rad) +
    ' Q' + xL + ',' + rt + ' ' + xL + ',' + (rt + rad) + ' V' + (yF - rad) + ' Q' + xL + ',' + yF + ' ' + (xL + rad) + ',' + yF +
    ' H' + (x - FB_R), color, 2.2, '6,4');
  fbPath(g, 'M' + (x - FB_R) + ',' + yB + ' H' + (xL + rad) + ' Q' + xL + ',' + yB + ' ' + xL + ',' + (yB + rad) +
    ' V' + (rb - rad) + ' Q' + xL + ',' + rb + ' ' + (xL + rad) + ',' + rb + ' H' + (xR - rad) +
    ' Q' + xR + ',' + rb + ' ' + xR + ',' + (rb - rad) + ' V' + (yB + rad) + ' Q' + xR + ',' + yB + ' ' + (xR - rad) + ',' + yB +
    ' H' + (x + FB_R), color, 2.2, '6,4');
}

function fbRenderInsert() {
  var s = FBPH[fbPhase] || 0, X = 925;
  gAIns.clear(); gBIns.clear();
  var fade = s >= 2;
  fbPtr.forEach(function (p) {
    if ((p.owner === 3 && p.kind === 'right') || (p.owner === 17 && p.kind === 'left'))
      p.el.opacity(fade ? 0.12 : 1);
  });
  if (fbSegA317) fbSegA317.opacity(fade ? 0.12 : 1);
  if (s === 0) return;

  var dash = (s === 4) ? null : '8,6';

  /* panel (a) */
  if (s === 1) {
    fbNewNode(gAIns, X, 62, false);
    fbHalo(fbTxt(gAIns, 'new single-node tree', X + 30, 112, 20, '#0d5c2e', true));
  } else {
    fbArrow(gAIns, fbN[3].x + FB_R, fbRowA[0], X - FB_R, fbRowA[0], FB_GR,2.4, dash);
    fbArrow(gAIns, X + FB_R, fbRowA[0], fbN[17].x - FB_R, fbRowA[0], FB_GR, 2.4, dash);
    fbNewNode(gAIns, X, fbRowA[0], s === 4);
    fbHalo(fbTxt(gAIns, 'O(1): 4 pointer writes', 995, 100, 20, '#0d5c2e', true));
    if (s >= 3) fbHalo(fbTxt(gAIns, '21 > 3  \u21D2  H.min unchanged', 1255, 100, 20, FB_OR, true));
  }

  /* panel (b) */
  var yF = fbRowB[0] - 11, yB = fbRowB[0] + 11;
  if (s === 1) {
    fbNewNode(gBIns, X, 592, false);
    fbSelfLoops(gBIns, X, 592, FB_GR);
    fbHalo(fbTxt(gBIns, 'x.left = x.right = x', 1175, 585, 20, '#0d5c2e', true));
  } else {
    fbArrow(gBIns, fbN[3].x + FB_R + 2, yF, X - FB_R - 2, yF, FB_GR, 2.4, dash);
    fbArrow(gBIns, X + FB_R + 2, yF, fbN[17].x - FB_R - 2, yF, FB_GR, 2.4, dash);
    fbArrow(gBIns, X - FB_R - 2, yB, fbN[3].x + FB_R + 2, yB, FB_GR, 2.4, dash);
    fbArrow(gBIns, fbN[17].x - FB_R - 2, yB, X + FB_R + 2, yB, FB_GR, 2.4, dash);
    fbNewNode(gBIns, X, fbRowB[0], s === 4);
    fbHalo(fbTxt(gBIns, '4 pointer updates \u2192 O(1)', 960, 802, 21, '#0d5c2e', true));
    if (s >= 3) fbHalo(fbTxt(gBIns, '21 > 3  \u21D2  H.min stays at 3', 1085, 608, 21, FB_OR, true));
  }
}

/* ---------- controls ---------- */
var fbView = 'both';
function update_viewMode(v) {
  fbView = v;
  var c = String(v).charAt(1);
  if (c === 'a') { gA.show(); gB.hide(); fbDraw.viewbox(0, 0, 1560, 500); }
  else if (c === 'b') { gA.hide(); gB.show(); fbDraw.viewbox(0, 545, 1560, 585); }
  else { gA.show(); gB.show(); fbDraw.viewbox(0, 0, 1560, 1130); }
}
function update_insertPhase(v) { fbPhase = v; fbRenderInsert(); }

/* ---------- demo player ---------- */
var fbSteps = [
  {
    title: 'The abstract view', view: 'both', phase: 'before', mark: false, sel: null,
    narration: 'Five min-heap-ordered trees sit in a root list, drawn as a dashed line; H.min points at the smallest root, 3. Each tree obeys the heap property, but nothing constrains the trees\u2019 shapes relative to one another.'
  },
  {
    title: 'Marked nodes', view: '(a) abstract trees', phase: 'before', mark: true, sel: null,
    narration: 'Nodes 18, 39, and 26 are black: each has lost one child since it last became the child of another node. A second loss would cut it into the root list.'
  },
  {
    title: 'The same heap, in pointers', view: '(b) pointer structure', phase: 'before', mark: false, sel: 18,
    narration: 'Switch to the pointer view: the dashed root line becomes a circular doubly linked list, and every set of siblings gets its own circular list. Click any node to light up its parent, child, left, and right pointers.'
  },
  {
    title: 'Why circular and doubly linked', view: '(b) pointer structure', phase: 'before', mark: false, sel: 30,
    narration: 'Click node 30 or 35: a lone child\u2019s left and right pointers loop back to itself. Circular lists mean splicing a node in or out touches only a fixed number of pointers, with no head or tail special cases.'
  },
  {
    title: 'Insert key 21', view: '(b) pointer structure', phase: 'spliced into root list', mark: false, sel: null,
    narration: 'Create a single-node tree holding 21 and splice it into the root list between two existing roots by rewiring four pointers.'
  },
  {
    title: 'Check H.min', view: '(b) pointer structure', phase: 'H.min updated', mark: false, sel: null,
    narration: 'Compare 21 against H.min\u2019s key 3. Since 21 > 3, H.min stays on 3. The whole operation was a constant number of pointer writes and one comparison \u2014 O(1), with no consolidation.'
  },
  {
    title: 'Back to the abstract picture', view: '(a) abstract trees', phase: 'done', mark: false, sel: null,
    narration: 'Return to the tree view: the heap now has six roots. The lazy, unconsolidated root list is exactly what buys Fibonacci heaps their fast inserts and decrease-keys.'
  }
];
var fbCur = 0;

function fbApplyStep(i) {
  fbCur = Math.max(0, Math.min(fbSteps.length - 1, i));
  var s = fbSteps[fbCur];
  var vm = document.getElementById('viewModeInput');
  var ip = document.getElementById('insertPhaseInput');
  if (vm) { vm.value = s.view; }
  if (ip) { ip.value = s.phase; }
  update_viewMode(s.view);
  update_insertPhase(s.phase);
  fbClearHL();
  if (s.sel) fbSelect(s.sel);
  fbShowMarked(s.mark);
  document.getElementById('stepTitle').textContent = s.title;
  document.getElementById('demoNarration').textContent = s.narration;
  document.getElementById('stepLabel').textContent = 'step ' + (fbCur + 1) + ' / ' + fbSteps.length;
}
function nextStep() { fbApplyStep(fbCur + 1); }
function prevStep() { fbApplyStep(fbCur - 1); }

/* ---------- init ---------- */
fbApplyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
