// @FIGURE_CODE_BEGIN
var FB_SERIF = "'Times New Roman', Times, serif";
var FB_GRAY = '#d9d9d9', FB_OR = '#e07b1a', FB_GR = '#1f8f4a', FB_STAT = '#4a5158';
var FB_R = 33, FB_KEY = 32;
/* type scale (user units; viewBox width 1530) — panel letters > H.min > callouts */
var SZ_PANEL = 50, SZ_HMIN = 44, SZ_CALL = 30, SZ_HL = 28, SZ_PLATE = 24;

var fbDraw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
var VB_BOTH = [20, 0, 1530, 1390], VB_A = [20, 0, 1530, 520], VB_B = [20, 500, 1530, 890];
fbDraw.viewbox(VB_BOTH[0], VB_BOTH[1], VB_BOTH[2], VB_BOTH[3]);

/* ---------- markers ---------- */
var fbMarks = {};
function fbMarker(c) {
  if (!fbMarks[c]) {
    fbMarks[c] = fbDraw.marker(5, 5, function (add) {
      add.path('M0,0 L5,2.5 L0,5 Z').fill(c);
    }).ref(4.4, 2.5);
  }
  return fbMarks[c];
}

/* ---------- data ---------- */
var fbDefs = [
  { k: 23, x: 180, d: 0, m: false, p: null },
  { k: 7, x: 385, d: 0, m: false, p: null },
  { k: 3, x: 720, d: 0, m: false, p: null },
  { k: 17, x: 1130, d: 0, m: false, p: null },
  { k: 24, x: 1390, d: 0, m: false, p: null },
  { k: 18, x: 585, d: 1, m: true, p: 3 },
  { k: 52, x: 722, d: 1, m: false, p: 3 },
  { k: 38, x: 858, d: 1, m: false, p: 3 },
  { k: 30, x: 1130, d: 1, m: false, p: 17 },
  { k: 26, x: 1330, d: 1, m: true, p: 24 },
  { k: 46, x: 1462, d: 1, m: false, p: 24 },
  { k: 39, x: 585, d: 2, m: true, p: 18 },
  { k: 41, x: 858, d: 2, m: false, p: 38 },
  { k: 35, x: 1330, d: 2, m: false, p: 26 }
];
var fbN = {};
fbDefs.forEach(function (d) { fbN[d.k] = d; });

var fbLists = [
  { ids: [23, 7, 3, 17, 24], d: 0 },
  { ids: [18, 52, 38], d: 1 },
  { ids: [30], d: 1 },
  { ids: [26, 46], d: 1 },
  { ids: [39], d: 2 },
  { ids: [41], d: 2 },
  { ids: [35], d: 2 }
];
fbLists.forEach(function (L) {
  L.ids.forEach(function (id, i) { fbN[id].list = L.ids; fbN[id].idx = i; });
});
var FBCHILD = { 3: 52, 17: 30, 24: 26, 18: 39, 38: 41, 26: 35 };

var fbRowA = [175, 310, 445];
var fbRowB = [760, 1000, 1240];

/* ---------- groups (z-order) ---------- */
var gA = fbDraw.group();
var gAEdges = gA.group(), gANodes = gA.group(), gAIns = gA.group();
var gB = fbDraw.group();
var gBArr = gB.group(), gBNodes = gB.group(), gBIns = gB.group();
var gStatic = fbDraw.group();
var gMark = fbDraw.group();
var fbHL = fbDraw.group();

/* ---------- text helpers ---------- */
function fbTxt(g, s, cx, cy, size, color, italic, weight) {
  var t = g.text(String(s)).font({
    family: FB_SERIF, size: size, anchor: 'middle',
    style: italic ? 'italic' : 'normal', weight: weight || 'normal'
  }).fill(color);
  t.center(cx, cy);
  return t;
}
function fbHalo(t, w) {
  t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': w || 5, 'stroke-linejoin': 'round' });
  return t;
}
/* boxed label: opaque plate so overlay text never sits on an arrow */
function fbBox(g, s, cx, cy, size, color) {
  var t = fbTxt(g, s, cx, cy, size, color, true);
  var b = t.bbox();
  var r = g.rect(b.width + 20, b.height + 11).radius(7).center(cx, cy)
    .fill('#fff').opacity(0.95).stroke({ color: color, width: 1.2, opacity: 0.45 });
  t.before(r);
  return t;
}
function fbArrow(g, x1, y1, x2, y2, color, w, dash) {
  var l = g.line(x1, y1, x2, y2).stroke({ color: color, width: w || 2 });
  if (dash) l.attr('stroke-dasharray', dash);
  l.marker('end', fbMarker(color));
  return l;
}
function fbPath(g, d, color, w, dash) {
  var p = g.path(d).fill('none').stroke({ color: color, width: w || 2 });
  if (dash) p.attr('stroke-dasharray', dash);
  p.marker('end', fbMarker(color));
  return p;
}
function fbLeader(g, x1, y1, x2, y2) {
  g.line(x1, y1, x2, y2).stroke({ color: FB_STAT, width: 1.4, opacity: 0.75 });
}

var fbPtr = [];
function fbReg(el, owner, kind, lx, ly, w) {
  fbPtr.push({ el: el, owner: owner, kind: kind, lx: lx, ly: ly, base: '#000', w: w || 2 });
  return el;
}

/* ---------- circular doubly linked list rails (panel b) ---------- */
function fbDrawList(g, ids, y) {
  var xs = ids.map(function (id) { return fbN[id].x; });
  var n = ids.length, solo = (n === 1);
  var yF = y - 15, yB = y + 15;
  var rt = y - (solo ? 58 : 76), rb = y + (solo ? 58 : 76), rad = solo ? 14 : 18;
  var pad = solo ? 34 : 46;
  var xL = xs[0] - FB_R - pad, xR = xs[n - 1] + FB_R + pad;
  var i;
  for (i = 0; i < n - 1; i++) {
    fbReg(fbArrow(g, xs[i] + FB_R + 2, yF, xs[i + 1] - FB_R - 2, yF, '#000', 2),
      ids[i], 'right', (xs[i] + xs[i + 1]) / 2, yF - 29);
    fbReg(fbArrow(g, xs[i + 1] - FB_R - 2, yB, xs[i] + FB_R + 2, yB, '#000', 2),
      ids[i + 1], 'left', (xs[i] + xs[i + 1]) / 2, yB + 31);
  }
  var df = 'M' + (xs[n - 1] + FB_R + 2) + ',' + yF + ' H' + (xR - rad) +
    ' Q' + xR + ',' + yF + ' ' + xR + ',' + (yF - rad) +
    ' V' + (rt + rad) + ' Q' + xR + ',' + rt + ' ' + (xR - rad) + ',' + rt +
    ' H' + (xL + rad) + ' Q' + xL + ',' + rt + ' ' + xL + ',' + (rt + rad) +
    ' V' + (yF - rad) + ' Q' + xL + ',' + yF + ' ' + (xL + rad) + ',' + yF +
    ' H' + (xs[0] - FB_R - 2);
  fbReg(fbPath(g, df, '#000', 2), ids[n - 1], 'right', (xL + xR) / 2, rt - 22);
  var db = 'M' + (xs[0] - FB_R - 2) + ',' + yB + ' H' + (xL + rad) +
    ' Q' + xL + ',' + yB + ' ' + xL + ',' + (yB + rad) +
    ' V' + (rb - rad) + ' Q' + xL + ',' + rb + ' ' + (xL + rad) + ',' + rb +
